var o={slug:"ultrasonic",title:"Mission: The Ultrasonic",subtitle:"Help a robot sense an obstacle before it gets too close.",summary:"Explore a robot, find its sensor, and use echoes to make a safe stopping rule.",badge:"PING",color:"#3fbf3f",activity:"discover",activityLabel:"Distance-sensing activities",activityInstruction:"Activity 1: set the robot alarm distance and test two settings. Activity 2: set the vacuum speed and trigger distance, then detect all four walls. Choose an activity below.",exploreTitle:"How does a robot sense distance?",exploreInstruction:"Turn the robot. Find its two round sensor faces. A sound pulse travels out, bounces off an object, and returns as an echo. A longer wait means a farther object.",difficulty:1,topics:["ultrasonic sensor","echo","distance","obstacle detection"],classIds:["BrickX"],storyVideoUrl:"https://www.youtube.com/embed/KUR64yNy2ew",warmupVideoUrl:"https://www.youtube.com/embed/pn1qJET81a4",storyQuestions:[],quiz:[],parts:[{id:"sensor",label:"Ultrasonic sensor",fact:"The two round faces send ultrasonic sound and listen for its echo. The robot uses the waiting time to work out distance.",help:"Find the pair of round metal faces at the front of the robot."},{id:"controller",label:"Controller board",fact:"The controller follows a program. It reads the distance and tells the motors when to go or stop.",help:"Find the circuit board on top, toward the back of the robot."},{id:"wires",label:"Connecting wires",fact:"Wires connect the sensor and other parts to the controller. They carry power and electrical signals.",help:"Find the curved coloured cables above the robot."},{id:"wheels",label:"Wheels",fact:"Motors turn the wheels to move the robot. Our stopping rule tells them to stop before an obstacle.",help:"Find the round tyres along the sides of the robot."}]};export{o as a};
